class Solution {
  public int countPartitions(int[] nums, int k) {
    final int MOD = 1_000_000_007;
    int n = nums.length;
    int[] dp = new int[n + 1];
    long[] prefix = new long[n + 2]; // prefix[i] = dp[0] + ... + dp[i - 1]
    dp[0] = 1;
    prefix[1] = 1;
    int[] maxQ = new int[n], minQ = new int[n];
    int maxHead = 0, maxTail = 0, minHead = 0, minTail = 0, left = 0;
    for (int i = 0; i < n; i++) {
      while (maxTail > maxHead && nums[maxQ[maxTail - 1]] <= nums[i]) maxTail--;
      maxQ[maxTail++] = i;
      while (minTail > minHead && nums[minQ[minTail - 1]] >= nums[i]) minTail--;
      minQ[minTail++] = i;
      while (nums[maxQ[maxHead]] - nums[minQ[minHead]] > k) {
        left++;
        if (maxQ[maxHead] < left) maxHead++;
        if (minQ[minHead] < left) minHead++;
      }
      // the last segment is nums[j..i] for every j in [left, i]
      dp[i + 1] = (int) ((prefix[i + 1] - prefix[left] + MOD) % MOD);
      prefix[i + 2] = (prefix[i + 1] + dp[i + 1]) % MOD;
    }
    return dp[n];
  }
}
